pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public { 
        c = new C();
        // deployer of C in setUp() is address(this) by default; record it as admin
        admin = address(this);
    }

    // Fuzz the candidate newOwner address. The general rule: when called by admin, c.owner() == newOwner.
    function testFuzz_property(address newOwner) public {
        // keep domain wide; disallow zero address only if desired — but the reference should accept address(0) as a valid owner
        // We do not constrain; the reference must satisfy for all inputs.

        // call setOwner as the admin (this contract is the deployer/admin)
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // exactly one assertion: if the call returned true (succeeded) then the public getter owner() must equal the provided newOwner.
        // We assert the universal property that for all fuzzed newOwner, if setOwner succeeds then owner == newOwner.
        // The mutant that resets owner to address(0) before assignment may cause owner != newOwner for some inputs.
        assertTrue(!ok || address(c.owner()) == newOwner);
    }
}

