contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: caller tries to call setOwner with a candidate newOwner.
    // General rule: only the deployer (admin) may change owner; any other caller's attempt must not change owner.
    function testFuzz_property(address caller, address candidate) public {
        // keep wide domain but avoid zero-address candidate which is admissible but less interesting
        vm.assume(caller != address(0));
        // ensure candidate can be any address (including deployer or others)

        // record owner before the call
        address ownerBefore = c.owner();

        // The deployer (admin) is the test contract's setUp deployer? Actually c was deployed in setUp by this test contract,
        // so the admin is address(this). To simulate a non-admin caller, we prank as `caller`.

        bool ok;
        vm.prank(caller);
        try c.setOwner(candidate) {
            ok = true;
        } catch {
            ok = false;
        }

        address ownerAfter = c.owner();

        // Exact one assertion: For the reference contract, only the admin (the deployer of c, which is this test contract)
        // can change owner; therefore if the call was made by anyone other than address(this), owner must remain unchanged.
        // The mutant that checks msg.sender == owner instead of admin will allow the current owner to change owner when
        // caller == ownerBefore; thus for some fuzzed inputs (caller == ownerBefore and caller != address(this)) the mutant
        // will change owner but the reference will not. We express the universal property as follows:
        // If the caller is NOT the original admin (address(this)), then ownerAfter == ownerBefore must hold.
        if (caller != address(this)) {
            assertTrue(ownerAfter == ownerBefore);
        } else {
            // if caller is admin, reference allows change or not depending on call success; still we must assert a tautology
            // that always holds: ownerAfter is either ownerBefore (if call reverted) or candidate (if succeeded). We don't assert here
            // because the single assert must be the one above that the reference satisfies for all inputs and the mutant breaks for some.
            // To satisfy the requirement of exactly one assertTrue in the test function, do nothing in this branch.
        }
    }
}

