pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        // test process account is deployer (forge's default test caller)
        deployer = address(this);
        c = new C();
    }

    // Fuzzed parameters: caller address who will attempt to call setOwner, and the newOwner to set.
    function testFuzz_property(address caller, address newOwner) public {
        // Broad admissible domain: avoid the zero address only because some contracts may treat it specially;
        // keep the domain wide otherwise so the fuzzer can find a case where caller != deployer but caller == current owner.
        // Allow caller and newOwner to be any address including equal to deployer; the property must hold for all.
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Ensure initial owner is the deployer (constructor set). Verify by reading public getter.
        address initialOwner = c.owner();
        assertTrue(initialOwner == deployer);

        // Scenario: let 'caller' attempt to set owner to 'newOwner'.
        // On the correct contract, only deployer (admin) can successfully call setOwner and change owner.
        // If caller != deployer, setOwner should not succeed (it will revert); if caller == deployer it should succeed.
        bool ok;
        vm.prank(caller);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: after the attempt, the owner equals newOwner iff the caller was the original admin (deployer).
        // This is the universal property: for all caller/newOwner, owner == newOwner exactly when caller == deployer.
        // The correct contract enforces this for every input; the mutant (checking owner instead of admin) allows caller==initialOwner
        // (which equals deployer initially) to change owner but later allows non-admin current owner to change owner, so the fuzzer can find inputs
        // where caller != deployer but owner == newOwner on the mutant — violating this universal property.
        address finalOwner = c.owner();
        // assertTrue over a relation that must hold for all admissible inputs on the reference implementation
        assertTrue((caller == deployer) == (finalOwner == newOwner));
    }
}

