pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        // tests are run with this contract as the deployer of the test file, but we capture address(this)
        deployer = address(this);
        c = new C();
    }

    // General rule to check: Only the original admin (the deployer) can change owner via setOwner.
    // Fuzz parameters: caller (who invokes setOwner) and newOwner (the address passed into setOwner).
    // We keep domain wide: any addresses except zero for new owner (owner could be zero in some tests but avoid trivial zero-case).
    function testFuzz_property(address caller, address newOwner) public {
        // Keep newOwner wide but avoid zero to ensure owner change is meaningful
        if (newOwner == address(0)) return;

        // Ensure we are not pruning the space of callers too much: allow any caller including deployer or others

        // Arrange: capture owner before call
        address ownerBefore = c.owner();

        // Act: have caller call setOwner(newOwner)
        // For EOAs (fuzzed addresses) we can vm.prank them and call. If caller equals address(this) it's fine.
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // Observe: owner after the call
        address ownerAfter = c.owner();

        // The invariant (single assert): On the correct contract, only the original admin (deployer) can change owner.
        // That means: if caller != deployer, then the call must not have succeeded in changing owner (ownerAfter == ownerBefore).
        // If caller == deployer, ownerAfter should equal newOwner if call succeeded.
        // We express a single assertTrue that captures the universal property for all inputs.

        // Build the boolean that must hold for the correct contract:
        bool correctBehavior;
        if (caller == deployer) {
            // deployer may change owner; if call indicated success then ownerAfter must equal newOwner, else owner unchanged
            correctBehavior = (!ok && ownerAfter == ownerBefore) || (ok && ownerAfter == newOwner);
        } else {
            // non-deployer must NOT be able to change owner: owner must remain the same regardless of ok flag
            correctBehavior = (ownerAfter == ownerBefore);
        }

        assertTrue(correctBehavior);
    }
}

