import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        c = new C();
        // the test runner (this contract) deployed C, so address(this) is the deployer/admin
        deployer = address(this);
    }

    // fuzzed parameters: caller trying to call setOwner, and the newOwner value
    function testFuzz_property(address caller, address newOwner) public {
        // Keep domain wide but avoid the trivial case where caller is the deployer/admin
        // We want to assert that when a non-admin calls setOwner, owner's value remains the deployer.
        vm.assume(caller != deployer);

        // Ensure caller is not zero to keep realistic EOA
        vm.assume(caller != address(0));

        // Arrange: the initial owner of c should be the deployer (set in constructor)
        // Confirm initial owner equals deployer via public getter
        assertTrue(c.owner() == deployer);

        // Act: have the fuzzed caller call setOwner(newOwner)
        vm.prank(caller);
        // We call setOwner; whether it reverts or returns, we catch via try/catch would be allowed,
        // but here we perform the call and ignore revert — we only care about final owner.
        // To avoid test revert, use low-level call through this helper path: call from caller into c.setOwner
        // But vm.prank ensures msg.sender; a failing require will revert and revert the test. To avoid that,
        // we use try/catch on the external call to capture possible revert and continue.
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert the universal property: when a non-admin (caller != deployer) attempts setOwner,
        // the owner of c remains the original deployer. This holds for the correct contract for ALL inputs,
        // but the mutant (which checks msg.sender == owner) allows a non-admin who is the current owner to
        // change owner, so for some fuzzed inputs the mutant will violate this assertion.
        assertTrue(c.owner() == deployer);
    }
}

