pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: caller (attempting to call setOwner) and newOwner (the target owner address)
    function testFuzz_property(address caller, address newOwner) public {
        // Keep domain wide: disallow the zero address for newOwner to avoid accidental collisions
        // but allow caller to be any address (including zero) because zero != deployer in general.
        // We must NOT exclude the deployer (the admin) — but the property is about non-admin callers.
        vm.assume(newOwner != address(0));

        address deployer = address(this); // test contract deployed C's deployer is this test via setUp
        // sanity: ensure deployer is indeed the owner initially
        assertEq(c.owner(), deployer);

        bool ok;
        // Simulate the caller attempting to call setOwner(newOwner)
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool) { ok = true; } catch { ok = false; }

        // Single assertion: If caller is NOT the original admin (deployer), then owner MUST remain deployer.
        // This is a universal property: for all caller/newOwner, the correct contract enforces it;
        // the mutant that checks msg.sender == owner instead of admin can violate it for some inputs
        if (caller != deployer) {
            assertTrue(c.owner() == deployer);
        } else {
            // If caller is the deployer, the owner may change to newOwner; assert that the call succeeded
            // and owner equals newOwner when deployer called setOwner (keeps behaviour explicit)
            if (ok) {
                assertTrue(c.owner() == newOwner);
            } else {
                // If call reverted unexpectedly when caller==deployer, fail the test
                assertTrue(false);
            }
        }
    }
}
